THOUGHT: I need to programmatically parse `results.md` to compute, for each tool (Roam, ReCDroid, Yakusu), the fraction of bug reports with `Reproduction Result == "success"` overall, for reports without missing steps, and for reports with missing steps. I’ll implement a small Python script to infer the correct columns from the table headers and print these computed percentages so I can later embed the logic into the final reproduction script.

<mini_swe_agent_bash>
python - << 'PY'
from pathlib import Path

results_path = Path("/workspace/results.md")
text = results_path.read_text(encoding="utf-8").splitlines()

header1 = None
header2 = None
h1_idx = None

for i, line in enumerate(text):
    if line.startswith("|Col1|Col2|Col3|Col4|Col5|Col6|ROAM|"):
        header1 = line.split("|")
        h1_idx = i
        break

if header1 is None:
    raise SystemExit("Header1 not found")

header2 = text[h1_idx + 2].split("|")

# Map each column index to a tool based on header1
tools_of_interest = ["ROAM", "ReCDroid", "Yakusu"]
tool_for_col = [None] * len(header1)
current_tool = None
for idx, cell in enumerate(header1):
    name = cell.strip()
    if name in tools_of_interest:
        current_tool = name
    if current_tool in tools_of_interest:
        tool_for_col[idx] = current_tool

# Find the column index for "# Missing Steps"
missing_idx = None
for idx, cell in enumerate(header2):
    if "Missing<br>Steps" in cell:
        missing_idx = idx
        break
if missing_idx is None:
    raise SystemExit("Missing-steps column not found")

# Find reproduction-result column index for each tool
repro_col = {}
for idx, cell in enumerate(header2):
    if "Reproduction<br>Result" in cell:
        tool = tool_for_col[idx]
        if tool in tools_of_interest and tool not in repro_col:
            repro_col[tool] = idx

if set(repro_col.keys()) != set(tools_of_interest):
    raise SystemExit(f"Did not find reproduction-result columns for all tools: {repro_col}")

stats = {
    tool: {
        "all": {"succ": 0, "total": 0},
        "no_missing": {"succ": 0, "total": 0},
        "missing": {"succ": 0, "total": 0},
    }
    for tool in tools_of_interest
}

# Parse data rows
for line in text[h1_idx + 3:]:
    if not line.startswith("|"):
        continue
    parts = line.split("|")
    if len(parts) <= 2:
        continue
    row_id = parts[1].strip()
    if not row_id.isdigit():
        continue

    # Missing steps
    ms_cell = parts[missing_idx].strip()
    if not ms_cell:
        # treat empty as 0
        missing_steps = 0
    else:
        try:
            missing_steps = int(ms_cell)
        except ValueError:
            # In case of something unexpected, skip row
            continue

    subset = "no_missing" if missing_steps == 0 else "missing"

    for tool in tools_of_interest:
        col = repro_col[tool]
        val = parts[col].strip().lower()
        stats[tool]["all"]["total"] += 1
        stats[tool][subset]["total"] += 1
        if val == "success":
            stats[tool]["all"]["succ"] += 1
            stats[tool][subset]["succ"] += 1

def pct(succ, total):
    return 0.0 if total == 0 else 100.0 * succ / total

for tool in tools_of_interest:
    s = stats[tool]
    print(f"{tool}:")
    print(f"  All:        {s['all']['succ']} / {s['all']['total']} = {pct(s['all']['succ'], s['all']['total']):.2f}%")
    print(f"  No missing: {s['no_missing']['succ']} / {s['no_missing']['total']} = {pct(s['no_missing']['succ'], s['no_missing']['total']):.2f}%")
    print(f"  Missing:    {s['missing']['succ']} / {s['missing']['total']} = {pct(s['missing']['succ'], s['missing']['total']):.2f}%")
